(18562,'_site_transient_community-events-72af4ad3f965fccc84919b8ea68043cd','a:4:{s:9:\"sandboxed\";b:0;s:5:\"error\";N;s:8:\"location\";a:1:{s:2:\"ip\";s:12:\"172.64.145.0\";}s:6:\"events\";a:6:{i:0;a:10:{s:4:\"type\";s:8:\"wordcamp\";s:5:\"title\";s:11:\"WordCamp US\";s:3:\"url\";s:29:\"https://us.wordcamp.org/2026/\";s:6:\"meetup\";s:0:\"\";s:10:\"meetup_url\";s:0:\"\";s:4:\"date\";s:19:\"2026-08-16 09:00:00\";s:8:\"end_date\";s:19:\"2026-08-19 17:00:00\";s:20:\"start_unix_timestamp\";i:1786896000;s:18:\"end_unix_timestamp\";i:1787184000;s:8:\"location\";a:4:{s:8:\"location\";s:16:\"Phoenix, Arizona\";s:7:\"country\";s:2:\"US\";s:8:\"latitude\";d:33.4483771;s:9:\"longitude\";d:-112.0740373;}}i:1;a:10:{s:4:\"type\";s:6:\"meetup\";s:5:\"title\";s:55:\"WordPress Helpdesk: Fix, support, improve your website.\";s:3:\"url\";s:50:\"https://www.meetup.com/sanjosewp/events/315050890/\";s:6:\"meetup\";s:59:\"SJ WP Helpdesk: Fix, Support, Improve, Build; your website.\";s:10:\"meetup_url\";s:33:\"https://www.meetup.com/sanjosewp/\";s:4:\"date\";s:19:\"2026-06-18 18:00:00\";s:8:\"end_date\";s:19:\"2026-06-18 21:00:00\";s:20:\"start_unix_timestamp\";i:1781830800;s:18:\"end_unix_timestamp\";i:1781841600;s:8:\"location\";a:4:{s:8:\"location\";s:6:\"Online\";s:7:\"country\";s:2:\"US\";s:8:\"latitude\";d:37.26;s:9:\"longitude\";d:-121.92;}}i:2;a:10:{s:4:\"type\";s:6:\"meetup\";s:5:\"title\";s:55:\"WordPress Helpdesk: Fix, support, improve your website.\";s:3:\"url\";s:61:\"https://www.meetup.com/santa-cruz-wordpress/events/315050885/\";s:6:\"meetup\";s:59:\"SC WP Helpdesk: Fix, Support, Improve, Build; your website.\";s:10:\"meetup_url\";s:44:\"https://www.meetup.com/santa-cruz-wordpress/\";s:4:\"date\";s:19:\"2026-06-18 18:00:00\";s:8:\"end_date\";s:19:\"2026-06-18 21:00:00\";s:20:\"start_unix_timestamp\";i:1781830800;s:18:\"end_unix_timestamp\";i:1781841600;s:8:\"location\";a:4:{s:8:\"location\";s:6:\"Online\";s:7:\"country\";s:2:\"US\";s:8:\"latitude\";d:36.99;s:9:\"longitude\";d:-122.06;}}i:3;a:10:{s:4:\"type\";s:6:\"meetup\";s:5:\"title\";s:76:\"Kick-off: In 7 Wochen zur eigenen Website – WordPress-Lerngruppe Juli 2026\";s:3:\"url\";s:73:\"https://www.meetup.com/learn-wordpress-online-workshops/events/315067852/\";s:6:\"meetup\";s:32:\"Learn WordPress Online Workshops\";s:10:\"meetup_url\";s:56:\"https://www.meetup.com/learn-wordpress-online-workshops/\";s:4:\"date\";s:19:\"2026-07-14 10:00:00\";s:8:\"end_date\";s:19:\"2026-07-14 11:00:00\";s:20:\"start_unix_timestamp\";i:1784048400;s:18:\"end_unix_timestamp\";i:1784052000;s:8:\"location\";a:4:{s:8:\"location\";s:6:\"Online\";s:7:\"country\";s:2:\"US\";s:8:\"latitude\";d:37.78;s:9:\"longitude\";d:-122.42;}}i:4;a:10:{s:4:\"type\";s:6:\"meetup\";s:5:\"title\";s:70:\"From “Inaccessible” to Inclusive: A Practical PDF Remediation Demo\";s:3:\"url\";s:77:\"https://www.meetup.com/wordpress-accessibility-meetup-group/events/315054797/\";s:6:\"meetup\";s:30:\"WordPress Accessibility Meetup\";s:10:\"meetup_url\";s:60:\"https://www.meetup.com/wordpress-accessibility-meetup-group/\";s:4:\"date\";s:19:\"2026-07-21 08:00:00\";s:8:\"end_date\";s:19:\"2026-07-21 09:00:00\";s:20:\"start_unix_timestamp\";i:1784646000;s:18:\"end_unix_timestamp\";i:1784649600;s:8:\"location\";a:4:{s:8:\"location\";s:6:\"Online\";s:7:\"country\";s:2:\"US\";s:8:\"latitude\";d:37.75;s:9:\"longitude\";d:-122.42;}}i:5;a:10:{s:4:\"type\";s:8:\"wordcamp\";s:5:\"title\";s:27:\"WordCamp Santa Clarita 2026\";s:3:\"url\";s:39:\"https://santaclarita.wordcamp.org/2026/\";s:6:\"meetup\";s:0:\"\";s:10:\"meetup_url\";s:0:\"\";s:4:\"date\";s:19:\"2026-07-24 00:00:00\";s:8:\"end_date\";s:19:\"2026-07-25 00:00:00\";s:20:\"start_unix_timestamp\";i:1784876400;s:18:\"end_unix_timestamp\";i:1784962800;s:8:\"location\";a:4:{s:8:\"location\";s:25:\"Santa Clarita, California\";s:7:\"country\";s:2:\"US\";s:8:\"latitude\";d:34.4039725;s:9:\"longitude\";d:-118.5686669;}}}}','off'),
