(18960,'_site_transient_community-events-35474a4b268afd678e610ad12209cccc','a:4:{s:9:\"sandboxed\";b:0;s:5:\"error\";N;s:8:\"location\";a:1:{s:2:\"ip\";s:11:\"172.67.72.0\";}s:6:\"events\";a:5:{i:0;a:10:{s:4:\"type\";s:8:\"wordcamp\";s:5:\"title\";s:11:\"WordCamp US\";s:3:\"url\";s:29:\"https://us.wordcamp.org/2026/\";s:6:\"meetup\";s:0:\"\";s:10:\"meetup_url\";s:0:\"\";s:4:\"date\";s:19:\"2026-08-16 09:00:00\";s:8:\"end_date\";s:19:\"2026-08-19 17:00:00\";s:20:\"start_unix_timestamp\";i:1786896000;s:18:\"end_unix_timestamp\";i:1787184000;s:8:\"location\";a:4:{s:8:\"location\";s:16:\"Phoenix, Arizona\";s:7:\"country\";s:2:\"US\";s:8:\"latitude\";d:33.4483771;s:9:\"longitude\";d:-112.0740373;}}i:1;a:10:{s:4:\"type\";s:6:\"meetup\";s:5:\"title\";s:76:\"Kick-off: In 7 Wochen zur eigenen Website – WordPress-Lerngruppe Juli 2026\";s:3:\"url\";s:73:\"https://www.meetup.com/learn-wordpress-online-workshops/events/315067852/\";s:6:\"meetup\";s:32:\"Learn WordPress Online Workshops\";s:10:\"meetup_url\";s:56:\"https://www.meetup.com/learn-wordpress-online-workshops/\";s:4:\"date\";s:19:\"2026-07-14 10:00:00\";s:8:\"end_date\";s:19:\"2026-07-14 11:00:00\";s:20:\"start_unix_timestamp\";i:1784048400;s:18:\"end_unix_timestamp\";i:1784052000;s:8:\"location\";a:4:{s:8:\"location\";s:6:\"Online\";s:7:\"country\";s:2:\"US\";s:8:\"latitude\";d:37.78;s:9:\"longitude\";d:-122.42;}}i:2;a:10:{s:4:\"type\";s:6:\"meetup\";s:5:\"title\";s:70:\"From “Inaccessible” to Inclusive: A Practical PDF Remediation Demo\";s:3:\"url\";s:77:\"https://www.meetup.com/wordpress-accessibility-meetup-group/events/315054797/\";s:6:\"meetup\";s:30:\"WordPress Accessibility Meetup\";s:10:\"meetup_url\";s:60:\"https://www.meetup.com/wordpress-accessibility-meetup-group/\";s:4:\"date\";s:19:\"2026-07-21 08:00:00\";s:8:\"end_date\";s:19:\"2026-07-21 09:00:00\";s:20:\"start_unix_timestamp\";i:1784646000;s:18:\"end_unix_timestamp\";i:1784649600;s:8:\"location\";a:4:{s:8:\"location\";s:6:\"Online\";s:7:\"country\";s: