ntainer mx-auto\"} -->\n<div class=\"wp-block-column container mx-auto\"><!-- wp:heading {\"className\":\"uoh\"} -->\n<h2 class=\"wp-block-heading uoh\">Les projets</h2>\n<!-- /wp:heading -->\n\n<!-- wp:create-block/unit-projets -->\n<p class=\"wp-block-create-block-unit-projets\">Unit Projets – hello from the saved content!</p>\n<!-- /wp:create-block/unit-projets -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"className\":\"d-flex w-100 justify-content-center align-items-center py-5\"} -->\n<div class=\"wp-block-column d-flex w-100 justify-content-center align-items-center py-5\"><!-- wp:paragraph -->\n<p><a href=\"http://un.test/nos-projets/\" class=\"btn btn-uoh\">Voir tous les projets</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:create-block/unit-portraits -->\n<p class=\"wp-block-create-block-unit-portraits\">Unit Portraits – hello from the saved content!</p>\n<!-- /wp:create-block/unit-portraits -->\n\n<!-- wp:columns {\"className\":\"membres\"} -->\n<div class=\"wp-block-columns membres\"><!-- wp:column {\"className\":\"py-md-6 py-4\"} -->\n<div class=\"wp-block-column py-md-6 py-4\"><!-- wp:wp-bootstrap-blocks/container -->\n<!-- wp:heading {\"className\":\"iut\"} -->\n<h2 class=\"wp-block-heading iut\">Établissements membres</h2>\n<!-- /wp:heading -->\n\n<!-- wp:partnersgrid/block-esnext -->\n<div id=\"partnersgrid-block-root\" class=\"partners-grid\"></div>\n<!-- /wp:partnersgrid/block-esnext -->\n<!-- /wp:wp-bootstrap-blocks/container --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Accueil','','inherit','closed','closed','','31-revision-v1','','','2025-07-22 10:23:54','2025-07-22 08:23:54','',31,'http://un.test/?p=14233',0,'revision','',0),
(14235,2,'2025-07-22 10:29:05','2025-07-22 08:29:05','<!-- wp:wp-bootstrap-blocks/row {\"template\":\"custom\",\"noGutters\":true,\"className\":\"top-banner\"} -->\n<!-- wp:wp-bootstrap-blocks/column {\"sizeMd\":12} -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:wp-bootstrap-blocks/container -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":1,\"className\":\"pt-md-6 pt-4 mb-4\"} -->\n<h1 class=\"wp-block-heading pt-md-6 pt-4 mb-4\">Des ressources éducatives<br>libres pour tous</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><a href=\"http://un.test/ressources/\" class=\"btn btn-uved\"><i class=\"fa-solid fa-book\"></i> Le catalogue</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n<!-- /wp:wp-bootstrap-blocks/container -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n<!-- /wp:wp-bootstrap-blocks/column -->\n<!-- /wp:wp-bootstrap-blocks/row -->\n\n<!-- wp:columns {\"className\":\"container\"} -->\n<div class=\"wp-block-columns container\"><!-- wp:column {\"width\":\"100%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:100%\"><!-- wp:create-block/unit-news {\"title_class\":\"aunege\"} /--></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"className\":\"projets pattern-gauche\"} -->\n<div class=\"wp-block-column projets pattern-gauche\"><!-- wp:columns {\"className\":\"mb-0\"} -->\n<div class=\"wp-block-columns mb-0\"><!-- wp:column {\"className\":\"container mx-auto\"} -->\n<div class=\"wp-block-column container mx-auto\"><!-- wp:heading {\"className\":\"uoh\"} -->\n<h2 class=\"wp-block-heading uoh\">Les projets</h2>\n<!-- /wp:heading -->\n\n<!-- wp:create-block/unit-projets -->\n<p class=\"wp-block-create-block-unit-projets\">Unit Projets – hello from the saved content!</p>\n<!-- /wp:create-block/unit-projets -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"className\":\"d-flex w-100 justify-content-center align-items-center py-5\"} -->\n<div class=\"wp-block-column d-flex w-100 justify-content-center align-items-center py-5\"><!-- wp:paragraph -->\n<p><a href=\"http://un.test/nos-projets/\" class=\"btn btn-uoh\">Voir tous les projets</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:create-block/unit-portraits -->\n<p class=\"wp-block-create-block-unit-portraits\">Unit Portraits – hello from the saved content!</p>\n<!-- /wp:create-block/unit-portraits -->\n\n<!-- wp:columns {\"className\":\"membres\"} -->\n<div class=\"wp-block-columns membres\"><!-- wp:column {\"className\":\"py-md-6 py-4\"} -->\n<div class=\"wp-block-column py-md-6 py-4\"><!-- wp:wp-bootstrap-blocks/container -->\n<!-- wp:heading {\"className\":\"iut\"} -->\n<h2 class=\"wp-block-heading iut\">Établissements membres</h2>\n<!-- /wp:heading -->\n\n<!-- wp:partnersgrid/block-esnext -->\n<div id=\"partnersgrid-block-root\" class=\"partners-grid\"></div>\n<!-- /wp:partnersgrid/block-esnext -->\n<!-- /wp:wp-bootstrap-blocks/container --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Accueil','','inherit','closed','closed','','31-revision-v1','','','2025-07-22 10:29:05','2025-07-22 08:29:05','',31,'http://un.test/?p=14235',0,'revision','',0),
(14237,2,'2025-07-23 14:13:18','2025-07-23 12:13:18','<!-- wp:heading {\"className\":\"uoh\"} -->\n<h2 class=\"wp-block-heading uoh\">Qu’est-ce que L’Université Numérique&nbsp;?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique est une association (loi 1901) composée de 6 universités numériques thématiques (UNT) françaises, dont la vocation est de mettre à la disposition des établissements d’enseignement supérieur (enseignants, étudiants) des ressources pédagogiques numériques pour les enseignements (classe inversée, présentiel enrichi, ressources complémentaires, formation à distance,…). La<strong> qualité technique, scientifique et pédagogique</strong> de ces ressources est validée par des universitaires compétents dans chaque domaine disciplinaire. Ces ressources sont libres d’accès et gratuites dans la grande majorité des cas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique couvre les domaines d’enseignement suivants : santé et sport, sciences de l’ingénieur, économie et gestion, humanités (arts, lettres et langues, sciences humaines et sociales), environnement et développement durable, technologie.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique s’adresse à l’ensemble de la <strong>communauté universitaire</strong> : enseignants, étudiants (pour apporter un complément pédagogique à leurs enseignements) et gouvernances (pour les accompagner à développer et à mettre en œuvre leur stratégie/politique numérique).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L\'Université Numérique et ses membres sont soutenus financièrement par le MESR dans le cadre d\'une convention d\'objectifs et de moyens depuis 2020.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"aunege\"} -->\n<h2 class=\"wp-block-heading aunege\">L’origine de L’Université Numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les « Universités numériques thématiques » (UNT) ont été créées à partir de 2003 par le ministère chargé de l’Enseignement supérieur français. Les UNT françaises[1]&nbsp;ne sont pas des établissements universitaires classiques, puisqu’elles n’inscrivent pas d’étudiants et ne dispensent ni grades ni diplômes. Bien que de formes juridiques différentes (GIP, fondation partenariale, association loi 1901, service commun interuniversitaire), les UNT sont toutes des&nbsp;<strong>groupements d’établissements d’enseignement supérieur</strong>&nbsp;qui produisent, diffusent et mutualisent, avec le soutien de l’État, des ressources pédagogiques numériques (ou éducatives libres).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Le 13 juin 2017, les 8 UNT françaises se sont coordonnées sous la forme d’une association loi 1901. Le 2 octobre 2019, le nombre d’UNT participant à l’association est passé à 6. L’Université Numérique, regroupe plus d’une centaine d’établissements d’enseignement supérieur et de recherche français.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>[1]&nbsp;sciences de l’ingénieur et technologie (<a href=\"http://www.unit.eu/\" target=\"_blank\" rel=\"noreferrer noopener\">UNIT</a>) – sciences fondamentales (<a href=\"https://www.unisciel.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNISCIEL</a>) – économie-gestion (<a href=\"http://www.aunege.org/\" target=\"_blank\" rel=\"noreferrer noopener\">AUNEGE</a>) – sciences humaines et sociales, langues et cultures (<a href=\"https://www.uoh.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UOH</a>) – sciences juridiques et politiques (<a href=\"https://www.unjf.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNJF</a>) – environnement et développement durable (<a href=\"http://www.uved.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UVED</a>) – sciences de la santé et du sport (<a href=\"https://www.uness.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNESS</a>) – technologie (<a href=\"https://www.iutenligne.net/\" target=\"_blank\" rel=\"noreferrer noopener\">IUT en Ligne</a>)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"uness\"} -->\n<h2 class=\"wp-block-heading uness\">Les missions des UNT</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT ont été créées dans un objectif de&nbsp;<strong>mutualisation</strong>, en vue d’encourager les usages du numérique lors des séances pédagogiques dans l’enseignement supérieur. Cette mutualisation passe par la production de ressources pédagogiques numériques, pour la plupart accessibles librement à travers les sites internet des UNT. Ces ressources sont conçues dans le but d’<strong>aider les enseignants dans leur pédagogie</strong>, contribuant ainsi à la rénovation des pédagogies et à l’innovation par le numérique dans l’enseignement supérieur.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Les principales missions des UNT sont&nbsp;:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>accompagner les étudiants de la Licence au Master, avec un soutien particulier en L1, l’ambition étant d’améliorer les taux de réussite&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>aider à l’orientation des étudiants et futurs étudiants&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>faciliter la formation tout au long de la vie&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>diffuser la connaissance pour toutes et tous dans un souci de service public&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>faciliter l’enseignement à distance, notamment à destination des personnes empêchées (en situation de handicap, prisonniers, etc.)&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>promouvoir les TICE&nbsp;et appuyer les établissements pour la mise en place des usages liés à la pédagogie numérique&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>co-construire et gérer des projets pluri-partenaires axés sur le numérique&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>promouvoir les établissements et les auteurs dans leurs spécialités&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>favoriser la mobilité internationale et l’intégration des étudiants étrangers&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>inscrire la France dans le mouvement mondial de libéralisation de l’accès au savoir.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>L’association L’Université Numérique promeut 6 UNT dans une vision commune. Elle vise à développer des actions collectives (Festival d’Automne du Numérique (FAN), appel à projets pour la production et la réingénierie de ressources à destination des publics « oui, si ») et à valoriser les actions de chacune des UNT et celles de leurs établissements, de manière plus visible et dans le respect de leurs spécificités.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":14241,\"sizeSlug\":\"full\",\"linkDestination\":\"media\",\"align\":\"center\",\"style\":{\"color\":[]}} -->\n<figure class=\"wp-block-image aligncenter size-full\"><a href=\"http://un.test/wp-content/uploads/2025/07/Collaboration-1-1030x687-1.jpg\"><img src=\"http://un.test/wp-content/uploads/2025/07/Collaboration-1-1030x687-1.jpg\" alt=\"\" class=\"wp-image-14241\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"className\":\"uved\"} -->\n<h2 class=\"wp-block-heading uved\">Les accompagnements possibles</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Par son action pour les établissements de l’enseignement supérieur, l’Université Numérique répond à multiples défis et objectifs&nbsp;:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Lutter contre l’échec en premier cycle</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Simplifier la situation des étudiants empêchés</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Favoriser l’intégration des étudiants en situation de handicap</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Servir d’appui à la mobilité internationale entrante et sortante</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Préserver des connaissances et compétences disciplinaires rares</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Appuyer la transformation et la mise en place de l’offre de formation des CUE</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Accompagner l’évolution des pratiques pédagogiques notamment avec le numérique</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Monter ou participer à des projets pluri-partenaires</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"className\":\"unit\"} -->\n<h2 class=\"wp-block-heading unit\">Les ressources pédagogiques numériques</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT mettent à disposition et diffusent environ 30.000 ressources éducatives libres dont elles ont souvent financé en partie la production. Elles peuvent en&nbsp;<strong>accompagner les usages</strong>. Elles produisent également des MOOC, des tests de positionnement transversaux et disciplinaires, des ressources de remédiation associées, des dispositifs de découverte des disciplines universitaires, des parcours de formation (ressources structurées et scénarios de formation), etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>De nombreuses ressources extérieures aux UNT (existantes, produites par les établissements) sont également indexées sur les portails disciplinaires.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L\'Université Numérique est fière d\'être le partenaire privilégié de <a href=\"https://www.canal-u.tv/\" target=\"_blank\" rel=\"noreferrer noopener\">Canal U</a>, la vidéothèque dédiée à l\'enseignement supérieur et la recherche. Remontant à nos débuts, les Universités Numériques Thématiques ont joué un rôle crucial dans le fonctionnement de Canal U, en particulier dans la gestion des disciplines pour le classement des vidéos, une collaboration qui s\'étend jusqu\'à l\'année 2022. Bien que la classification actuelle soit désormais indépendante, elle demeure un héritage des Universités Numériques Thématiques. Par ailleurs, les UNT disposent chacune d\'une chaine sur Canal-U.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Canal U se distingue en offrant un entrepôt OAI, des DOI et en utilisant le SupLomFr pour garantir une expérience utilisateur exceptionnelle. Notre partenariat avec l\'ABES va au-delà, avec l\'utilisation d\'IdREF, attribuant des identifiants uniques aux mots-clés et aux intervenants. Ainsi, leurs contributions audiovisuelles sont référencées au même titre que leurs écrits, renforçant la richesse et la pertinence de notre vidéothèque.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"uoh\"} -->\n<h2 class=\"wp-block-heading uoh\">La transformation pédagogique par le numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT contribuent à la rénovation de de la pédagogie en favorisant la créativité pédagogique par l’usage du numérique.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Elles sont devenues des acteurs incontournables de la transformation pédagogique par le numérique et sont complémentaires des autres acteurs du domaine.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"iut\"} -->\n<h2 class=\"wp-block-heading iut\">Les instances de L\'Université Numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Le conseil d\'administration est composé de :</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Vincent Beillevaire pour <a href=\"https://luniversitenumerique.fr/thematiques/sciences-ingenieur-technologie/\" target=\"_blank\" rel=\"noreferrer noopener\">UNIT</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Béatrice Boury pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/sante-et-sport/\" target=\"_blank\" rel=\"noreferrer noopener\">UNESS</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Jacques Dang pour <a href=\"https://luniversitenumerique.fr/thematiques/economie-gestion-marketing/\" target=\"_blank\" rel=\"noreferrer noopener\">AUNEGe</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Ollivier Haemmerlé pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/sciences-humaines-sociales-lettres-langues-arts/\" target=\"_blank\" rel=\"noreferrer noopener\">UOH</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Paula Caterino pour <a href=\"https://luniversitenumerique.fr/thematiques/enseignement-technologique/\" target=\"_blank\" rel=\"noreferrer noopener\">IUT en Ligne</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Delphine Pommeray pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/environnement-developpement-durable/\" target=\"_blank\" rel=\"noreferrer noopener\">UVED</a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Le bureau est composé de :</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Ollivier Haemmerlé, Président</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Jacques Dang, Secrétaire</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Vincent Beillevaire, Trésorier</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','L\'Université Numérique','','trash','closed','closed','','a-propos__trashed','','','2026-06-17 16:15:11','2026-06-17 14:15:11','',37,'http://un.test/?page_id=14237',1,'page','',0),
(14238,2,'2025-07-23 14:13:18','2025-07-23 12:13:18','<!-- wp:heading {\"advgbBlockControls\":[],\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">Qu’est-ce que L’Université Numérique&nbsp;?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique est une association (loi 1901) composée de 6 universités numériques thématiques (UNT) françaises, dont la vocation est de mettre à la disposition des établissements d’enseignement supérieur (enseignants, étudiants) des ressources pédagogiques numériques pour les enseignements (classe inversée, présentiel enrichi, ressources complémentaires, formation à distance,…). La<strong> qualité technique, scientifique et pédagogique</strong> de ces ressources est validée par des universitaires compétents dans chaque domaine disciplinaire. Ces ressources sont libres d’accès et gratuites dans la grande majorité des cas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique couvre les domaines d’enseignement suivants : santé et sport, sciences de l’ingénieur, économie et gestion, humanités (arts, lettres et langues, sciences humaines et sociales), environnement et développement durable, technologie.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique s’adresse à l’ensemble de la <strong>communauté universitaire</strong> : enseignants, étudiants (pour apporter un complément pédagogique à leurs enseignements) et gouvernances (pour les accompagner à développer et à mettre en œuvre leur stratégie/politique numérique).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L\'Université Numérique et ses membres sont soutenus financièrement par le MESR dans le cadre d\'une convention d\'objectifs et de moyens depuis 2020.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"advgbBlockControls\":[],\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">L’origine de L’Université Numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les « Universités numériques thématiques » (UNT) ont été créées à partir de 2003 par le ministère chargé de l’Enseignement supérieur français. Les UNT françaises[1]&nbsp;ne sont pas des établissements universitaires classiques, puisqu’elles n’inscrivent pas d’étudiants et ne dispensent ni grades ni diplômes. Bien que de formes juridiques différentes (GIP, fondation partenariale, association loi 1901, service commun interuniversitaire), les UNT sont toutes des&nbsp;<strong>groupements d’établissements d’enseignement supérieur</strong>&nbsp;qui produisent, diffusent et mutualisent, avec le soutien de l’État, des ressources pédagogiques numériques (ou éducatives libres).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Le 13 juin 2017, les 8 UNT françaises se sont coordonnées sous la forme d’une association loi 1901. Le 2 octobre 2019, le nombre d’UNT participant à l’association est passé à 6. L’Université Numérique, regroupe plus d’une centaine d’établissements d’enseignement supérieur et de recherche français.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>[1]&nbsp;sciences de l’ingénieur et technologie (<a href=\"http://www.unit.eu/\" target=\"_blank\" rel=\"noreferrer noopener\">UNIT</a>) – sciences fondamentales (<a href=\"https://www.unisciel.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNISCIEL</a>) – économie-gestion (<a href=\"http://www.aunege.org/\" target=\"_blank\" rel=\"noreferrer noopener\">AUNEGE</a>) – sciences humaines et sociales, langues et cultures (<a href=\"https://www.uoh.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UOH</a>) – sciences juridiques et politiques (<a href=\"https://www.unjf.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNJF</a>) – environnement et développement durable (<a href=\"http://www.uved.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UVED</a>) – sciences de la santé et du sport (<a href=\"https://www.uness.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNESS</a>) – technologie (<a href=\"https://www.iutenligne.net/\" target=\"_blank\" rel=\"noreferrer noopener\">IUT en Ligne</a>)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"advgbBlockControls\":[],\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">Les missions des UNT</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT ont été créées dans un objectif de&nbsp;<strong>mutualisation</strong>, en vue d’encourager les usages du numérique lors des séances pédagogiques dans l’enseignement supérieur. Cette mutualisation passe par la production de ressources pédagogiques numériques, pour la plupart accessibles librement à travers les sites internet des UNT. Ces ressources sont conçues dans le but d’<strong>aider les enseignants dans leur pédagogie</strong>, contribuant ainsi à la rénovation des pédagogies et à l’innovation par le numérique dans l’enseignement supérieur.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Les principales missions des UNT sont&nbsp;:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>accompagner les étudiants de la Licence au Master, avec un soutien particulier en L1, l’ambition étant d’améliorer les taux de réussite&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>aider à l’orientation des étudiants et futurs étudiants&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>faciliter la formation tout au long de la vie&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>diffuser la connaissance pour toutes et tous dans un souci de service public&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>faciliter l’enseignement à distance, notamment à destination des personnes empêchées (en situation de handicap, prisonniers, etc.)&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>promouvoir les TICE&nbsp;et appuyer les établissements pour la mise en place des usages liés à la pédagogie numérique&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>co-construire et gérer des projets pluri-partenaires axés sur le numérique&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>promouvoir les établissements et les auteurs dans leurs spécialités&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>favoriser la mobilité internationale et l’intégration des étudiants étrangers&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>inscrire la France dans le mouvement mondial de libéralisation de l’accès au savoir.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>L’association L’Université Numérique promeut 6 UNT dans une vision commune. Elle vise à développer des actions collectives (Festival d’Automne du Numérique (FAN), appel à projets pour la production et la réingénierie de ressources à destination des publics « oui, si ») et à valoriser les actions de chacune des UNT et celles de leurs établissements, de manière plus visible et dans le respect de leurs spécificités.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"align\":\"center\",\"id\":3268,\"sizeSlug\":\"large\",\"linkDestination\":\"media\",\"style\":{\"color\":[]}} -->\n<figure class=\"wp-block-image aligncenter size-large\"><a href=\"https://luniversitenumerique.fr/wp-content/uploads/2018/11/Collaboration-1-e1689944038422.jpg\"><img src=\"https://luniversitenumerique.fr/wp-content/uploads/2018/11/Collaboration-1-1030x687.jpg\" alt=\"Université Numérique\" class=\"wp-image-3268\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"advgbBlockControls\":[],\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">Les accompagnements possibles</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Par son action pour les établissements de l’enseignement supérieur, l’Université Numérique répond à multiples défis et objectifs&nbsp;:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Lutter contre l’échec en premier cycle</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Simplifier la situation des étudiants empêchés</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Favoriser l’intégration des étudiants en situation de handicap</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Servir d’appui à la mobilité internationale entrante et sortante</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Préserver des connaissances et compétences disciplinaires rares</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Appuyer la transformation et la mise en place de l’offre de formation des CUE</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Accompagner l’évolution des pratiques pédagogiques notamment avec le numérique</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Monter ou participer à des projets pluri-partenaires</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"advgbBlockControls\":[],\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">Les ressources pédagogiques numériques</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT mettent à disposition et diffusent environ 30.000 ressources éducatives libres dont elles ont souvent financé en partie la production. Elles peuvent en&nbsp;<strong>accompagner les usages</strong>. Elles produisent également des MOOC, des tests de positionnement transversaux et disciplinaires, des ressources de remédiation associées, des dispositifs de découverte des disciplines universitaires, des parcours de formation (ressources structurées et scénarios de formation), etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>De nombreuses ressources extérieures aux UNT (existantes, produites par les établissements) sont également indexées sur les portails disciplinaires.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L\'Université Numérique est fière d\'être le partenaire privilégié de <a href=\"https://www.canal-u.tv/\" target=\"_blank\" rel=\"noreferrer noopener\">Canal U</a>, la vidéothèque dédiée à l\'enseignement supérieur et la recherche. Remontant à nos débuts, les Universités Numériques Thématiques ont joué un rôle crucial dans le fonctionnement de Canal U, en particulier dans la gestion des disciplines pour le classement des vidéos, une collaboration qui s\'étend jusqu\'à l\'année 2022. Bien que la classification actuelle soit désormais indépendante, elle demeure un héritage des Universités Numériques Thématiques. Par ailleurs, les UNT disposent chacune d\'une chaine sur Canal-U.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Canal U se distingue en offrant un entrepôt OAI, des DOI et en utilisant le SupLomFr pour garantir une expérience utilisateur exceptionnelle. Notre partenariat avec l\'ABES va au-delà, avec l\'utilisation d\'IdREF, attribuant des identifiants uniques aux mots-clés et aux intervenants. Ainsi, leurs contributions audiovisuelles sont référencées au même titre que leurs écrits, renforçant la richesse et la pertinence de notre vidéothèque.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"advgbBlockControls\":[],\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">La transformation pédagogique par le numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT contribuent à la rénovation de de la pédagogie en favorisant la créativité pédagogique par l’usage du numérique.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Elles sont devenues des acteurs incontournables de la transformation pédagogique par le numérique et sont complémentaires des autres acteurs du domaine.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"advgbBlockControls\":[],\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">Les instances de L\'Université Numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Le conseil d\'administration est composé de :</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Vincent Beillevaire pour <a href=\"https://luniversitenumerique.fr/thematiques/sciences-ingenieur-technologie/\" target=\"_blank\" rel=\"noreferrer noopener\">UNIT</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Béatrice Boury pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/sante-et-sport/\" target=\"_blank\" rel=\"noreferrer noopener\">UNESS</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Jacques Dang pour <a href=\"https://luniversitenumerique.fr/thematiques/economie-gestion-marketing/\" target=\"_blank\" rel=\"noreferrer noopener\">AUNEGe</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Ollivier Haemmerlé pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/sciences-humaines-sociales-lettres-langues-arts/\" target=\"_blank\" rel=\"noreferrer noopener\">UOH</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Paula Caterino pour <a href=\"https://luniversitenumerique.fr/thematiques/enseignement-technologique/\" target=\"_blank\" rel=\"noreferrer noopener\">IUT en Ligne</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Delphine Pommeray pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/environnement-developpement-durable/\" target=\"_blank\" rel=\"noreferrer noopener\">UVED</a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Le bureau est composé de :</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Ollivier Haemmerlé, Président</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Jacques Dang, Secrétaire</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Vincent Beillevaire, Trésorier</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','A propos','','inherit','closed','closed','','14237-revision-v1','','','2025-07-23 14:13:18','2025-07-23 12:13:18','',14237,'http://un.test/?p=14238',0,'revision','',0),
(14240,2,'2025-07-23 14:14:18','2025-07-23 12:14:18','<!-- wp:heading {\"advgbBlockControls\":[],\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">Qu’est-ce que L’Université Numérique&nbsp;?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique est une association (loi 1901) composée de 6 universités numériques thématiques (UNT) françaises, dont la vocation est de mettre à la disposition des établissements d’enseignement supérieur (enseignants, étudiants) des ressources pédagogiques numériques pour les enseignements (classe inversée, présentiel enrichi, ressources complémentaires, formation à distance,…). La<strong> qualité technique, scientifique et pédagogique</strong> de ces ressources est validée par des universitaires compétents dans chaque domaine disciplinaire. Ces ressources sont libres d’accès et gratuites dans la grande majorité des cas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique couvre les domaines d’enseignement suivants : santé et sport, sciences de l’ingénieur, économie et gestion, humanités (arts, lettres et langues, sciences humaines et sociales), environnement et développement durable, technologie.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique s’adresse à l’ensemble de la <strong>communauté universitaire</strong> : enseignants, étudiants (pour apporter un complément pédagogique à leurs enseignements) et gouvernances (pour les accompagner à développer et à mettre en œuvre leur stratégie/politique numérique).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L\'Université Numérique et ses membres sont soutenus financièrement par le MESR dans le cadre d\'une convention d\'objectifs et de moyens depuis 2020.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"advgbBlockControls\":[],\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">L’origine de L’Université Numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les « Universités numériques thématiques » (UNT) ont été créées à partir de 2003 par le ministère chargé de l’Enseignement supérieur français. Les UNT françaises[1]&nbsp;ne sont pas des établissements universitaires classiques, puisqu’elles n’inscrivent pas d’étudiants et ne dispensent ni grades ni diplômes. Bien que de formes juridiques différentes (GIP, fondation partenariale, association loi 1901, service commun interuniversitaire), les UNT sont toutes des&nbsp;<strong>groupements d’établissements d’enseignement supérieur</strong>&nbsp;qui produisent, diffusent et mutualisent, avec le soutien de l’État, des ressources pédagogiques numériques (ou éducatives libres).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Le 13 juin 2017, les 8 UNT françaises se sont coordonnées sous la forme d’une association loi 1901. Le 2 octobre 2019, le nombre d’UNT participant à l’association est passé à 6. L’Université Numérique, regroupe plus d’une centaine d’établissements d’enseignement supérieur et de recherche français.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>[1]&nbsp;sciences de l’ingénieur et technologie (<a href=\"http://www.unit.eu/\" target=\"_blank\" rel=\"noreferrer noopener\">UNIT</a>) – sciences fondamentales (<a href=\"https://www.unisciel.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNISCIEL</a>) – économie-gestion (<a href=\"http://www.aunege.org/\" target=\"_blank\" rel=\"noreferrer noopener\">AUNEGE</a>) – sciences humaines et sociales, langues et cultures (<a href=\"https://www.uoh.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UOH</a>) – sciences juridiques et politiques (<a href=\"https://www.unjf.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNJF</a>) – environnement et développement durable (<a href=\"http://www.uved.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UVED</a>) – sciences de la santé et du sport (<a href=\"https://www.uness.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNESS</a>) – technologie (<a href=\"https://www.iutenligne.net/\" target=\"_blank\" rel=\"noreferrer noopener\">IUT en Ligne</a>)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"advgbBlockControls\":[],\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">Les missions des UNT</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT ont été créées dans un objectif de&nbsp;<strong>mutualisation</strong>, en vue d’encourager les usages du numérique lors des séances pédagogiques dans l’enseignement supérieur. Cette mutualisation passe par la production de ressources pédagogiques numériques, pour la plupart accessibles librement à travers les sites internet des UNT. Ces ressources sont conçues dans le but d’<strong>aider les enseignants dans leur pédagogie</strong>, contribuant ainsi à la rénovation des pédagogies et à l’innovation par le numérique dans l’enseignement supérieur.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Les principales missions des UNT sont&nbsp;:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>accompagner les étudiants de la Licence au Master, avec un soutien particulier en L1, l’ambition étant d’améliorer les taux de réussite&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>aider à l’orientation des étudiants et futurs étudiants&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>faciliter la formation tout au long de la vie&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>diffuser la connaissance pour toutes et tous dans un souci de service public&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>faciliter l’enseignement à distance, notamment à destination des personnes empêchées (en situation de handicap, prisonniers, etc.)&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>promouvoir les TICE&nbsp;et appuyer les établissements pour la mise en place des usages liés à la pédagogie numérique&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>co-construire et gérer des projets pluri-partenaires axés sur le numérique&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>promouvoir les établissements et les auteurs dans leurs spécialités&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>favoriser la mobilité internationale et l’intégration des étudiants étrangers&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>inscrire la France dans le mouvement mondial de libéralisation de l’accès au savoir.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>L’association L’Université Numérique promeut 6 UNT dans une vision commune. Elle vise à développer des actions collectives (Festival d’Automne du Numérique (FAN), appel à projets pour la production et la réingénierie de ressources à destination des publics « oui, si ») et à valoriser les actions de chacune des UNT et celles de leurs établissements, de manière plus visible et dans le respect de leurs spécificités.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"align\":\"center\",\"id\":3268,\"sizeSlug\":\"large\",\"linkDestination\":\"media\",\"style\":{\"color\":[]}} -->\n<figure class=\"wp-block-image aligncenter size-large\"><a href=\"https://luniversitenumerique.fr/wp-content/uploads/2018/11/Collaboration-1-e1689944038422.jpg\"><img src=\"https://luniversitenumerique.fr/wp-content/uploads/2018/11/Collaboration-1-1030x687.jpg\" alt=\"Université Numérique\" class=\"wp-image-3268\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"advgbBlockControls\":[],\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">Les accompagnements possibles</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Par son action pour les établissements de l’enseignement supérieur, l’Université Numérique répond à multiples défis et objectifs&nbsp;:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Lutter contre l’échec en premier cycle</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Simplifier la situation des étudiants empêchés</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Favoriser l’intégration des étudiants en situation de handicap</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Servir d’appui à la mobilité internationale entrante et sortante</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Préserver des connaissances et compétences disciplinaires rares</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Appuyer la transformation et la mise en place de l’offre de formation des CUE</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Accompagner l’évolution des pratiques pédagogiques notamment avec le numérique</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Monter ou participer à des projets pluri-partenaires</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"advgbBlockControls\":[],\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">Les ressources pédagogiques numériques</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT mettent à disposition et diffusent environ 30.000 ressources éducatives libres dont elles ont souvent financé en partie la production. Elles peuvent en&nbsp;<strong>accompagner les usages</strong>. Elles produisent également des MOOC, des tests de positionnement transversaux et disciplinaires, des ressources de remédiation associées, des dispositifs de découverte des disciplines universitaires, des parcours de formation (ressources structurées et scénarios de formation), etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>De nombreuses ressources extérieures aux UNT (existantes, produites par les établissements) sont également indexées sur les portails disciplinaires.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L\'Université Numérique est fière d\'être le partenaire privilégié de <a href=\"https://www.canal-u.tv/\" target=\"_blank\" rel=\"noreferrer noopener\">Canal U</a>, la vidéothèque dédiée à l\'enseignement supérieur et la recherche. Remontant à nos débuts, les Universités Numériques Thématiques ont joué un rôle crucial dans le fonctionnement de Canal U, en particulier dans la gestion des disciplines pour le classement des vidéos, une collaboration qui s\'étend jusqu\'à l\'année 2022. Bien que la classification actuelle soit désormais indépendante, elle demeure un héritage des Universités Numériques Thématiques. Par ailleurs, les UNT disposent chacune d\'une chaine sur Canal-U.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Canal U se distingue en offrant un entrepôt OAI, des DOI et en utilisant le SupLomFr pour garantir une expérience utilisateur exceptionnelle. Notre partenariat avec l\'ABES va au-delà, avec l\'utilisation d\'IdREF, attribuant des identifiants uniques aux mots-clés et aux intervenants. Ainsi, leurs contributions audiovisuelles sont référencées au même titre que leurs écrits, renforçant la richesse et la pertinence de notre vidéothèque.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"advgbBlockControls\":[],\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">La transformation pédagogique par le numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT contribuent à la rénovation de de la pédagogie en favorisant la créativité pédagogique par l’usage du numérique.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Elles sont devenues des acteurs incontournables de la transformation pédagogique par le numérique et sont complémentaires des autres acteurs du domaine.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"advgbBlockControls\":[],\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">Les instances de L\'Université Numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Le conseil d\'administration est composé de :</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Vincent Beillevaire pour <a href=\"https://luniversitenumerique.fr/thematiques/sciences-ingenieur-technologie/\" target=\"_blank\" rel=\"noreferrer noopener\">UNIT</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Béatrice Boury pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/sante-et-sport/\" target=\"_blank\" rel=\"noreferrer noopener\">UNESS</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Jacques Dang pour <a href=\"https://luniversitenumerique.fr/thematiques/economie-gestion-marketing/\" target=\"_blank\" rel=\"noreferrer noopener\">AUNEGe</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Ollivier Haemmerlé pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/sciences-humaines-sociales-lettres-langues-arts/\" target=\"_blank\" rel=\"noreferrer noopener\">UOH</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Paula Caterino pour <a href=\"https://luniversitenumerique.fr/thematiques/enseignement-technologique/\" target=\"_blank\" rel=\"noreferrer noopener\">IUT en Ligne</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Delphine Pommeray pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/environnement-developpement-durable/\" target=\"_blank\" rel=\"noreferrer noopener\">UVED</a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Le bureau est composé de :</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Ollivier Haemmerlé, Président</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Jacques Dang, Secrétaire</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Vincent Beillevaire, Trésorier</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','L\'Université Numérique','','inherit','closed','closed','','14237-revision-v1','','','2025-07-23 14:14:18','2025-07-23 12:14:18','',14237,'http://un.test/?p=14240',0,'revision','',0),
(14241,2,'2025-07-23 14:20:24','2025-07-23 12:20:24','','Collaboration-1-1030x687','','inherit','open','closed','','collaboration-1-1030x687','','','2025-07-23 14:20:24','2025-07-23 12:20:24','',14237,'http://un.test/wp-content/uploads/2025/07/Collaboration-1-1030x687-1.jpg',0,'attachment','image/jpeg',0),
(14242,2,'2025-07-23 14:20:25','2025-07-23 12:20:25','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Qu’est-ce que L’Université Numérique&nbsp;?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique est une association (loi 1901) composée de 6 universités numériques thématiques (UNT) françaises, dont la vocation est de mettre à la disposition des établissements d’enseignement supérieur (enseignants, étudiants) des ressources pédagogiques numériques pour les enseignements (classe inversée, présentiel enrichi, ressources complémentaires, formation à distance,…). La<strong> qualité technique, scientifique et pédagogique</strong> de ces ressources est validée par des universitaires compétents dans chaque domaine disciplinaire. Ces ressources sont libres d’accès et gratuites dans la grande majorité des cas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique couvre les domaines d’enseignement suivants : santé et sport, sciences de l’ingénieur, économie et gestion, humanités (arts, lettres et langues, sciences humaines et sociales), environnement et développement durable, technologie.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique s’adresse à l’ensemble de la <strong>communauté universitaire</strong> : enseignants, étudiants (pour apporter un complément pédagogique à leurs enseignements) et gouvernances (pour les accompagner à développer et à mettre en œuvre leur stratégie/politique numérique).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L\'Université Numérique et ses membres sont soutenus financièrement par le MESR dans le cadre d\'une convention d\'objectifs et de moyens depuis 2020.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">L’origine de L’Université Numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les « Universités numériques thématiques » (UNT) ont été créées à partir de 2003 par le ministère chargé de l’Enseignement supérieur français. Les UNT françaises[1]&nbsp;ne sont pas des établissements universitaires classiques, puisqu’elles n’inscrivent pas d’étudiants et ne dispensent ni grades ni diplômes. Bien que de formes juridiques différentes (GIP, fondation partenariale, association loi 1901, service commun interuniversitaire), les UNT sont toutes des&nbsp;<strong>groupements d’établissements d’enseignement supérieur</strong>&nbsp;qui produisent, diffusent et mutualisent, avec le soutien de l’État, des ressources pédagogiques numériques (ou éducatives libres).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Le 13 juin 2017, les 8 UNT françaises se sont coordonnées sous la forme d’une association loi 1901. Le 2 octobre 2019, le nombre d’UNT participant à l’association est passé à 6. L’Université Numérique, regroupe plus d’une centaine d’établissements d’enseignement supérieur et de recherche français.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>[1]&nbsp;sciences de l’ingénieur et technologie (<a href=\"http://www.unit.eu/\" target=\"_blank\" rel=\"noreferrer noopener\">UNIT</a>) – sciences fondamentales (<a href=\"https://www.unisciel.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNISCIEL</a>) – économie-gestion (<a href=\"http://www.aunege.org/\" target=\"_blank\" rel=\"noreferrer noopener\">AUNEGE</a>) – sciences humaines et sociales, langues et cultures (<a href=\"https://www.uoh.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UOH</a>) – sciences juridiques et politiques (<a href=\"https://www.unjf.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNJF</a>) – environnement et développement durable (<a href=\"http://www.uved.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UVED</a>) – sciences de la santé et du sport (<a href=\"https://www.uness.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNESS</a>) – technologie (<a href=\"https://www.iutenligne.net/\" target=\"_blank\" rel=\"noreferrer noopener\">IUT en Ligne</a>)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Les missions des UNT</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT ont été créées dans un objectif de&nbsp;<strong>mutualisation</strong>, en vue d’encourager les usages du numérique lors des séances pédagogiques dans l’enseignement supérieur. Cette mutualisation passe par la production de ressources pédagogiques numériques, pour la plupart accessibles librement à travers les sites internet des UNT. Ces ressources sont conçues dans le but d’<strong>aider les enseignants dans leur pédagogie</strong>, contribuant ainsi à la rénovation des pédagogies et à l’innovation par le numérique dans l’enseignement supérieur.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Les principales missions des UNT sont&nbsp;:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>accompagner les étudiants de la Licence au Master, avec un soutien particulier en L1, l’ambition étant d’améliorer les taux de réussite&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>aider à l’orientation des étudiants et futurs étudiants&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>faciliter la formation tout au long de la vie&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>diffuser la connaissance pour toutes et tous dans un souci de service public&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>faciliter l’enseignement à distance, notamment à destination des personnes empêchées (en situation de handicap, prisonniers, etc.)&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>promouvoir les TICE&nbsp;et appuyer les établissements pour la mise en place des usages liés à la pédagogie numérique&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>co-construire et gérer des projets pluri-partenaires axés sur le numérique&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>promouvoir les établissements et les auteurs dans leurs spécialités&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>favoriser la mobilité internationale et l’intégration des étudiants étrangers&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>inscrire la France dans le mouvement mondial de libéralisation de l’accès au savoir.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>L’association L’Université Numérique promeut 6 UNT dans une vision commune. Elle vise à développer des actions collectives (Festival d’Automne du Numérique (FAN), appel à projets pour la production et la réingénierie de ressources à destination des publics « oui, si ») et à valoriser les actions de chacune des UNT et celles de leurs établissements, de manière plus visible et dans le respect de leurs spécificités.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":14241,\"sizeSlug\":\"large\",\"linkDestination\":\"media\",\"align\":\"center\",\"style\":{\"color\":[]}} -->\n<figure class=\"wp-block-image aligncenter size-large\"><a href=\"http://un.test/wp-content/uploads/2025/07/Collaboration-1-1030x687-1.jpg\"><img src=\"http://un.test/wp-content/uploads/2025/07/Collaboration-1-1030x687-1-1024x683.jpg\" alt=\"\" class=\"wp-image-14241\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Les accompagnements possibles</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Par son action pour les établissements de l’enseignement supérieur, l’Université Numérique répond à multiples défis et objectifs&nbsp;:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Lutter contre l’échec en premier cycle</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Simplifier la situation des étudiants empêchés</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Favoriser l’intégration des étudiants en situation de handicap</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Servir d’appui à la mobilité internationale entrante et sortante</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Préserver des connaissances et compétences disciplinaires rares</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Appuyer la transformation et la mise en place de l’offre de formation des CUE</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Accompagner l’évolution des pratiques pédagogiques notamment avec le numérique</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Monter ou participer à des projets pluri-partenaires</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Les ressources pédagogiques numériques</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT mettent à disposition et diffusent environ 30.000 ressources éducatives libres dont elles ont souvent financé en partie la production. Elles peuvent en&nbsp;<strong>accompagner les usages</strong>. Elles produisent également des MOOC, des tests de positionnement transversaux et disciplinaires, des ressources de remédiation associées, des dispositifs de découverte des disciplines universitaires, des parcours de formation (ressources structurées et scénarios de formation), etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>De nombreuses ressources extérieures aux UNT (existantes, produites par les établissements) sont également indexées sur les portails disciplinaires.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L\'Université Numérique est fière d\'être le partenaire privilégié de <a href=\"https://www.canal-u.tv/\" target=\"_blank\" rel=\"noreferrer noopener\">Canal U</a>, la vidéothèque dédiée à l\'enseignement supérieur et la recherche. Remontant à nos débuts, les Universités Numériques Thématiques ont joué un rôle crucial dans le fonctionnement de Canal U, en particulier dans la gestion des disciplines pour le classement des vidéos, une collaboration qui s\'étend jusqu\'à l\'année 2022. Bien que la classification actuelle soit désormais indépendante, elle demeure un héritage des Universités Numériques Thématiques. Par ailleurs, les UNT disposent chacune d\'une chaine sur Canal-U.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Canal U se distingue en offrant un entrepôt OAI, des DOI et en utilisant le SupLomFr pour garantir une expérience utilisateur exceptionnelle. Notre partenariat avec l\'ABES va au-delà, avec l\'utilisation d\'IdREF, attribuant des identifiants uniques aux mots-clés et aux intervenants. Ainsi, leurs contributions audiovisuelles sont référencées au même titre que leurs écrits, renforçant la richesse et la pertinence de notre vidéothèque.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">La transformation pédagogique par le numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT contribuent à la rénovation de de la pédagogie en favorisant la créativité pédagogique par l’usage du numérique.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Elles sont devenues des acteurs incontournables de la transformation pédagogique par le numérique et sont complémentaires des autres acteurs du domaine.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Les instances de L\'Université Numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Le conseil d\'administration est composé de :</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Vincent Beillevaire pour <a href=\"https://luniversitenumerique.fr/thematiques/sciences-ingenieur-technologie/\" target=\"_blank\" rel=\"noreferrer noopener\">UNIT</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Béatrice Boury pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/sante-et-sport/\" target=\"_blank\" rel=\"noreferrer noopener\">UNESS</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Jacques Dang pour <a href=\"https://luniversitenumerique.fr/thematiques/economie-gestion-marketing/\" target=\"_blank\" rel=\"noreferrer noopener\">AUNEGe</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Ollivier Haemmerlé pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/sciences-humaines-sociales-lettres-langues-arts/\" target=\"_blank\" rel=\"noreferrer noopener\">UOH</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Paula Caterino pour <a href=\"https://luniversitenumerique.fr/thematiques/enseignement-technologique/\" target=\"_blank\" rel=\"noreferrer noopener\">IUT en Ligne</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Delphine Pommeray pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/environnement-developpement-durable/\" target=\"_blank\" rel=\"noreferrer noopener\">UVED</a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Le bureau est composé de :</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Ollivier Haemmerlé, Président</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Jacques Dang, Secrétaire</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Vincent Beillevaire, Trésorier</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','L\'Université Numérique','','inherit','closed','closed','','14237-revision-v1','','','2025-07-23 14:20:25','2025-07-23 12:20:25','',14237,'http://un.test/?p=14242',0,'revision','',0),
(14243,2,'2025-07-23 14:20:41','2025-07-23 12:20:41','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Qu’est-ce que L’Université Numérique&nbsp;?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique est une association (loi 1901) composée de 6 universités numériques thématiques (UNT) françaises, dont la vocation est de mettre à la disposition des établissements d’enseignement supérieur (enseignants, étudiants) des ressources pédagogiques numériques pour les enseignements (classe inversée, présentiel enrichi, ressources complémentaires, formation à distance,…). La<strong> qualité technique, scientifique et pédagogique</strong> de ces ressources est validée par des universitaires compétents dans chaque domaine disciplinaire. Ces ressources sont libres d’accès et gratuites dans la grande majorité des cas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique couvre les domaines d’enseignement suivants : santé et sport, sciences de l’ingénieur, économie et gestion, humanités (arts, lettres et langues, sciences humaines et sociales), environnement et développement durable, technologie.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique s’adresse à l’ensemble de la <strong>communauté universitaire</strong> : enseignants, étudiants (pour apporter un complément pédagogique à leurs enseignements) et gouvernances (pour les accompagner à développer et à mettre en œuvre leur stratégie/politique numérique).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L\'Université Numérique et ses membres sont soutenus financièrement par le MESR dans le cadre d\'une convention d\'objectifs et de moyens depuis 2020.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">L’origine de L’Université Numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les « Universités numériques thématiques » (UNT) ont été créées à partir de 2003 par le ministère chargé de l’Enseignement supérieur français. Les UNT françaises[1]&nbsp;ne sont pas des établissements universitaires classiques, puisqu’elles n’inscrivent pas d’étudiants et ne dispensent ni grades ni diplômes. Bien que de formes juridiques différentes (GIP, fondation partenariale, association loi 1901, service commun interuniversitaire), les UNT sont toutes des&nbsp;<strong>groupements d’établissements d’enseignement supérieur</strong>&nbsp;qui produisent, diffusent et mutualisent, avec le soutien de l’État, des ressources pédagogiques numériques (ou éducatives libres).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Le 13 juin 2017, les 8 UNT françaises se sont coordonnées sous la forme d’une association loi 1901. Le 2 octobre 2019, le nombre d’UNT participant à l’association est passé à 6. L’Université Numérique, regroupe plus d’une centaine d’établissements d’enseignement supérieur et de recherche français.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>[1]&nbsp;sciences de l’ingénieur et technologie (<a href=\"http://www.unit.eu/\" target=\"_blank\" rel=\"noreferrer noopener\">UNIT</a>) – sciences fondamentales (<a href=\"https://www.unisciel.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNISCIEL</a>) – économie-gestion (<a href=\"http://www.aunege.org/\" target=\"_blank\" rel=\"noreferrer noopener\">AUNEGE</a>) – sciences humaines et sociales, langues et cultures (<a href=\"https://www.uoh.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UOH</a>) – sciences juridiques et politiques (<a href=\"https://www.unjf.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNJF</a>) – environnement et développement durable (<a href=\"http://www.uved.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UVED</a>) – sciences de la santé et du sport (<a href=\"https://www.uness.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNESS</a>) – technologie (<a href=\"https://www.iutenligne.net/\" target=\"_blank\" rel=\"noreferrer noopener\">IUT en Ligne</a>)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Les missions des UNT</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT ont été créées dans un objectif de&nbsp;<strong>mutualisation</strong>, en vue d’encourager les usages du numérique lors des séances pédagogiques dans l’enseignement supérieur. Cette mutualisation passe par la production de ressources pédagogiques numériques, pour la plupart accessibles librement à travers les sites internet des UNT. Ces ressources sont conçues dans le but d’<strong>aider les enseignants dans leur pédagogie</strong>, contribuant ainsi à la rénovation des pédagogies et à l’innovation par le numérique dans l’enseignement supérieur.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Les principales missions des UNT sont&nbsp;:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>accompagner les étudiants de la Licence au Master, avec un soutien particulier en L1, l’ambition étant d’améliorer les taux de réussite&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>aider à l’orientation des étudiants et futurs étudiants&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>faciliter la formation tout au long de la vie&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>diffuser la connaissance pour toutes et tous dans un souci de service public&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>faciliter l’enseignement à distance, notamment à destination des personnes empêchées (en situation de handicap, prisonniers, etc.)&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>promouvoir les TICE&nbsp;et appuyer les établissements pour la mise en place des usages liés à la pédagogie numérique&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>co-construire et gérer des projets pluri-partenaires axés sur le numérique&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>promouvoir les établissements et les auteurs dans leurs spécialités&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>favoriser la mobilité internationale et l’intégration des étudiants étrangers&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>inscrire la France dans le mouvement mondial de libéralisation de l’accès au savoir.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>L’association L’Université Numérique promeut 6 UNT dans une vision commune. Elle vise à développer des actions collectives (Festival d’Automne du Numérique (FAN), appel à projets pour la production et la réingénierie de ressources à destination des publics « oui, si ») et à valoriser les actions de chacune des UNT et celles de leurs établissements, de manière plus visible et dans le respect de leurs spécificités.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":14241,\"sizeSlug\":\"full\",\"linkDestination\":\"media\",\"align\":\"center\",\"style\":{\"color\":[]}} -->\n<figure class=\"wp-block-image aligncenter size-full\"><a href=\"http://un.test/wp-content/uploads/2025/07/Collaboration-1-1030x687-1.jpg\"><img src=\"http://un.test/wp-content/uploads/2025/07/Collaboration-1-1030x687-1.jpg\" alt=\"\" class=\"wp-image-14241\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Les accompagnements possibles</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Par son action pour les établissements de l’enseignement supérieur, l’Université Numérique répond à multiples défis et objectifs&nbsp;:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Lutter contre l’échec en premier cycle</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Simplifier la situation des étudiants empêchés</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Favoriser l’intégration des étudiants en situation de handicap</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Servir d’appui à la mobilité internationale entrante et sortante</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Préserver des connaissances et compétences disciplinaires rares</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Appuyer la transformation et la mise en place de l’offre de formation des CUE</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Accompagner l’évolution des pratiques pédagogiques notamment avec le numérique</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Monter ou participer à des projets pluri-partenaires</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Les ressources pédagogiques numériques</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT mettent à disposition et diffusent environ 30.000 ressources éducatives libres dont elles ont souvent financé en partie la production. Elles peuvent en&nbsp;<strong>accompagner les usages</strong>. Elles produisent également des MOOC, des tests de positionnement transversaux et disciplinaires, des ressources de remédiation associées, des dispositifs de découverte des disciplines universitaires, des parcours de formation (ressources structurées et scénarios de formation), etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>De nombreuses ressources extérieures aux UNT (existantes, produites par les établissements) sont également indexées sur les portails disciplinaires.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L\'Université Numérique est fière d\'être le partenaire privilégié de <a href=\"https://www.canal-u.tv/\" target=\"_blank\" rel=\"noreferrer noopener\">Canal U</a>, la vidéothèque dédiée à l\'enseignement supérieur et la recherche. Remontant à nos débuts, les Universités Numériques Thématiques ont joué un rôle crucial dans le fonctionnement de Canal U, en particulier dans la gestion des disciplines pour le classement des vidéos, une collaboration qui s\'étend jusqu\'à l\'année 2022. Bien que la classification actuelle soit désormais indépendante, elle demeure un héritage des Universités Numériques Thématiques. Par ailleurs, les UNT disposent chacune d\'une chaine sur Canal-U.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Canal U se distingue en offrant un entrepôt OAI, des DOI et en utilisant le SupLomFr pour garantir une expérience utilisateur exceptionnelle. Notre partenariat avec l\'ABES va au-delà, avec l\'utilisation d\'IdREF, attribuant des identifiants uniques aux mots-clés et aux intervenants. Ainsi, leurs contributions audiovisuelles sont référencées au même titre que leurs écrits, renforçant la richesse et la pertinence de notre vidéothèque.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">La transformation pédagogique par le numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT contribuent à la rénovation de de la pédagogie en favorisant la créativité pédagogique par l’usage du numérique.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Elles sont devenues des acteurs incontournables de la transformation pédagogique par le numérique et sont complémentaires des autres acteurs du domaine.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Les instances de L\'Université Numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Le conseil d\'administration est composé de :</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Vincent Beillevaire pour <a href=\"https://luniversitenumerique.fr/thematiques/sciences-ingenieur-technologie/\" target=\"_blank\" rel=\"noreferrer noopener\">UNIT</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Béatrice Boury pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/sante-et-sport/\" target=\"_blank\" rel=\"noreferrer noopener\">UNESS</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Jacques Dang pour <a href=\"https://luniversitenumerique.fr/thematiques/economie-gestion-marketing/\" target=\"_blank\" rel=\"noreferrer noopener\">AUNEGe</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Ollivier Haemmerlé pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/sciences-humaines-sociales-lettres-langues-arts/\" target=\"_blank\" rel=\"noreferrer noopener\">UOH</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Paula Caterino pour <a href=\"https://luniversitenumerique.fr/thematiques/enseignement-technologique/\" target=\"_blank\" rel=\"noreferrer noopener\">IUT en Ligne</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Delphine Pommeray pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/environnement-developpement-durable/\" target=\"_blank\" rel=\"noreferrer noopener\">UVED</a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Le bureau est composé de :</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Ollivier Haemmerlé, Président</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Jacques Dang, Secrétaire</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Vincent Beillevaire, Trésorier</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','L\'Université Numérique','','inherit','closed','closed','','14237-revision-v1','','','2025-07-23 14:20:41','2025-07-23 12:20:41','',14237,'http://un.test/?p=14243',0,'revision','',0),
(14244,2,'2025-07-23 14:35:54','2025-07-23 12:35:54','<!-- wp:heading {\"className\":\"uoh\"} -->\n<h2 class=\"wp-block-heading uoh\">Qu’est-ce que L’Université Numérique&nbsp;?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique est une association (loi 1901) composée de 6 universités numériques thématiques (UNT) françaises, dont la vocation est de mettre à la disposition des établissements d’enseignement supérieur (enseignants, étudiants) des ressources pédagogiques numériques pour les enseignements (classe inversée, présentiel enrichi, ressources complémentaires, formation à distance,…). La<strong> qualité technique, scientifique et pédagogique</strong> de ces ressources est validée par des universitaires compétents dans chaque domaine disciplinaire. Ces ressources sont libres d’accès et gratuites dans la grande majorité des cas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique couvre les domaines d’enseignement suivants : santé et sport, sciences de l’ingénieur, économie et gestion, humanités (arts, lettres et langues, sciences humaines et sociales), environnement et développement durable, technologie.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique s’adresse à l’ensemble de la <strong>communauté universitaire</strong> : enseignants, étudiants (pour apporter un complément pédagogique à leurs enseignements) et gouvernances (pour les accompagner à développer et à mettre en œuvre leur stratégie/politique numérique).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L\'Université Numérique et ses membres sont soutenus financièrement par le MESR dans le cadre d\'une convention d\'objectifs et de moyens depuis 2020.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"aunege\"} -->\n<h2 class=\"wp-block-heading aunege\">L’origine de L’Université Numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les « Universités numériques thématiques » (UNT) ont été créées à partir de 2003 par le ministère chargé de l’Enseignement supérieur français. Les UNT françaises[1]&nbsp;ne sont pas des établissements universitaires classiques, puisqu’elles n’inscrivent pas d’étudiants et ne dispensent ni grades ni diplômes. Bien que de formes juridiques différentes (GIP, fondation partenariale, association loi 1901, service commun interuniversitaire), les UNT sont toutes des&nbsp;<strong>groupements d’établissements d’enseignement supérieur</strong>&nbsp;qui produisent, diffusent et mutualisent, avec le soutien de l’État, des ressources pédagogiques numériques (ou éducatives libres).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Le 13 juin 2017, les 8 UNT françaises se sont coordonnées sous la forme d’une association loi 1901. Le 2 octobre 2019, le nombre d’UNT participant à l’association est passé à 6. L’Université Numérique, regroupe plus d’une centaine d’établissements d’enseignement supérieur et de recherche français.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>[1]&nbsp;sciences de l’ingénieur et technologie (<a href=\"http://www.unit.eu/\" target=\"_blank\" rel=\"noreferrer noopener\">UNIT</a>) – sciences fondamentales (<a href=\"https://www.unisciel.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNISCIEL</a>) – économie-gestion (<a href=\"http://www.aunege.org/\" target=\"_blank\" rel=\"noreferrer noopener\">AUNEGE</a>) – sciences humaines et sociales, langues et cultures (<a href=\"https://www.uoh.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UOH</a>) – sciences juridiques et politiques (<a href=\"https://www.unjf.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNJF</a>) – environnement et développement durable (<a href=\"http://www.uved.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UVED</a>) – sciences de la santé et du sport (<a href=\"https://www.uness.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNESS</a>) – technologie (<a href=\"https://www.iutenligne.net/\" target=\"_blank\" rel=\"noreferrer noopener\">IUT en Ligne</a>)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"uness\"} -->\n<h2 class=\"wp-block-heading uness\">Les missions des UNT</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT ont été créées dans un objectif de&nbsp;<strong>mutualisation</strong>, en vue d’encourager les usages du numérique lors des séances pédagogiques dans l’enseignement supérieur. Cette mutualisation passe par la production de ressources pédagogiques numériques, pour la plupart accessibles librement à travers les sites internet des UNT. Ces ressources sont conçues dans le but d’<strong>aider les enseignants dans leur pédagogie</strong>, contribuant ainsi à la rénovation des pédagogies et à l’innovation par le numérique dans l’enseignement supérieur.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Les principales missions des UNT sont&nbsp;:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>accompagner les étudiants de la Licence au Master, avec un soutien particulier en L1, l’ambition étant d’améliorer les taux de réussite&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>aider à l’orientation des étudiants et futurs étudiants&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>faciliter la formation tout au long de la vie&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>diffuser la connaissance pour toutes et tous dans un souci de service public&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>faciliter l’enseignement à distance, notamment à destination des personnes empêchées (en situation de handicap, prisonniers, etc.)&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>promouvoir les TICE&nbsp;et appuyer les établissements pour la mise en place des usages liés à la pédagogie numérique&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>co-construire et gérer des projets pluri-partenaires axés sur le numérique&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>promouvoir les établissements et les auteurs dans leurs spécialités&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>favoriser la mobilité internationale et l’intégration des étudiants étrangers&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>inscrire la France dans le mouvement mondial de libéralisation de l’accès au savoir.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>L’association L’Université Numérique promeut 6 UNT dans une vision commune. Elle vise à développer des actions collectives (Festival d’Automne du Numérique (FAN), appel à projets pour la production et la réingénierie de ressources à destination des publics « oui, si ») et à valoriser les actions de chacune des UNT et celles de leurs établissements, de manière plus visible et dans le respect de leurs spécificités.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":14241,\"sizeSlug\":\"full\",\"linkDestination\":\"media\",\"align\":\"center\",\"style\":{\"color\":[]}} -->\n<figure class=\"wp-block-image aligncenter size-full\"><a href=\"http://un.test/wp-content/uploads/2025/07/Collaboration-1-1030x687-1.jpg\"><img src=\"http://un.test/wp-content/uploads/2025/07/Collaboration-1-1030x687-1.jpg\" alt=\"\" class=\"wp-image-14241\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"className\":\"uved\"} -->\n<h2 class=\"wp-block-heading uved\">Les accompagnements possibles</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Par son action pour les établissements de l’enseignement supérieur, l’Université Numérique répond à multiples défis et objectifs&nbsp;:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Lutter contre l’échec en premier cycle</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Simplifier la situation des étudiants empêchés</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Favoriser l’intégration des étudiants en situation de handicap</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Servir d’appui à la mobilité internationale entrante et sortante</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Préserver des connaissances et compétences disciplinaires rares</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Appuyer la transformation et la mise en place de l’offre de formation des CUE</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Accompagner l’évolution des pratiques pédagogiques notamment avec le numérique</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Monter ou participer à des projets pluri-partenaires</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"className\":\"unit\"} -->\n<h2 class=\"wp-block-heading unit\">Les ressources pédagogiques numériques</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT mettent à disposition et diffusent environ 30.000 ressources éducatives libres dont elles ont souvent financé en partie la production. Elles peuvent en&nbsp;<strong>accompagner les usages</strong>. Elles produisent également des MOOC, des tests de positionnement transversaux et disciplinaires, des ressources de remédiation associées, des dispositifs de découverte des disciplines universitaires, des parcours de formation (ressources structurées et scénarios de formation), etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>De nombreuses ressources extérieures aux UNT (existantes, produites par les établissements) sont également indexées sur les portails disciplinaires.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L\'Université Numérique est fière d\'être le partenaire privilégié de <a href=\"https://www.canal-u.tv/\" target=\"_blank\" rel=\"noreferrer noopener\">Canal U</a>, la vidéothèque dédiée à l\'enseignement supérieur et la recherche. Remontant à nos débuts, les Universités Numériques Thématiques ont joué un rôle crucial dans le fonctionnement de Canal U, en particulier dans la gestion des disciplines pour le classement des vidéos, une collaboration qui s\'étend jusqu\'à l\'année 2022. Bien que la classification actuelle soit désormais indépendante, elle demeure un héritage des Universités Numériques Thématiques. Par ailleurs, les UNT disposent chacune d\'une chaine sur Canal-U.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Canal U se distingue en offrant un entrepôt OAI, des DOI et en utilisant le SupLomFr pour garantir une expérience utilisateur exceptionnelle. Notre partenariat avec l\'ABES va au-delà, avec l\'utilisation d\'IdREF, attribuant des identifiants uniques aux mots-clés et aux intervenants. Ainsi, leurs contributions audiovisuelles sont référencées au même titre que leurs écrits, renforçant la richesse et la pertinence de notre vidéothèque.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">La transformation pédagogique par le numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT contribuent à la rénovation de de la pédagogie en favorisant la créativité pédagogique par l’usage du numérique.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Elles sont devenues des acteurs incontournables de la transformation pédagogique par le numérique et sont complémentaires des autres acteurs du domaine.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"iut\"} -->\n<h2 class=\"wp-block-heading iut\">Les instances de L\'Université Numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Le conseil d\'administration est composé de :</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Vincent Beillevaire pour <a href=\"https://luniversitenumerique.fr/thematiques/sciences-ingenieur-technologie/\" target=\"_blank\" rel=\"noreferrer noopener\">UNIT</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Béatrice Boury pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/sante-et-sport/\" target=\"_blank\" rel=\"noreferrer noopener\">UNESS</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Jacques Dang pour <a href=\"https://luniversitenumerique.fr/thematiques/economie-gestion-marketing/\" target=\"_blank\" rel=\"noreferrer noopener\">AUNEGe</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Ollivier Haemmerlé pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/sciences-humaines-sociales-lettres-langues-arts/\" target=\"_blank\" rel=\"noreferrer noopener\">UOH</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Paula Caterino pour <a href=\"https://luniversitenumerique.fr/thematiques/enseignement-technologique/\" target=\"_blank\" rel=\"noreferrer noopener\">IUT en Ligne</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Delphine Pommeray pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/environnement-developpement-durable/\" target=\"_blank\" rel=\"noreferrer noopener\">UVED</a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Le bureau est composé de :</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Ollivier Haemmerlé, Président</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Jacques Dang, Secrétaire</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Vincent Beillevaire, Trésorier</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','L\'Université Numérique','','inherit','closed','closed','','14237-revision-v1','','','2025-07-23 14:35:54','2025-07-23 12:35:54','',14237,'http://un.test/?p=14244',0,'revision','',0),
(14245,2,'2025-07-23 14:37:38','2025-07-23 12:37:38','<!-- wp:heading {\"className\":\"uoh\"} -->\n<h2 class=\"wp-block-heading uoh\">Qu’est-ce que L’Université Numérique&nbsp;?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique est une association (loi 1901) composée de 6 universités numériques thématiques (UNT) françaises, dont la vocation est de mettre à la disposition des établissements d’enseignement supérieur (enseignants, étudiants) des ressources pédagogiques numériques pour les enseignements (classe inversée, présentiel enrichi, ressources complémentaires, formation à distance,…). La<strong> qualité technique, scientifique et pédagogique</strong> de ces ressources est validée par des universitaires compétents dans chaque domaine disciplinaire. Ces ressources sont libres d’accès et gratuites dans la grande majorité des cas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique couvre les domaines d’enseignement suivants : santé et sport, sciences de l’ingénieur, économie et gestion, humanités (arts, lettres et langues, sciences humaines et sociales), environnement et développement durable, technologie.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L’Université Numérique s’adresse à l’ensemble de la <strong>communauté universitaire</strong> : enseignants, étudiants (pour apporter un complément pédagogique à leurs enseignements) et gouvernances (pour les accompagner à développer et à mettre en œuvre leur stratégie/politique numérique).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L\'Université Numérique et ses membres sont soutenus financièrement par le MESR dans le cadre d\'une convention d\'objectifs et de moyens depuis 2020.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"aunege\"} -->\n<h2 class=\"wp-block-heading aunege\">L’origine de L’Université Numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les « Universités numériques thématiques » (UNT) ont été créées à partir de 2003 par le ministère chargé de l’Enseignement supérieur français. Les UNT françaises[1]&nbsp;ne sont pas des établissements universitaires classiques, puisqu’elles n’inscrivent pas d’étudiants et ne dispensent ni grades ni diplômes. Bien que de formes juridiques différentes (GIP, fondation partenariale, association loi 1901, service commun interuniversitaire), les UNT sont toutes des&nbsp;<strong>groupements d’établissements d’enseignement supérieur</strong>&nbsp;qui produisent, diffusent et mutualisent, avec le soutien de l’État, des ressources pédagogiques numériques (ou éducatives libres).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Le 13 juin 2017, les 8 UNT françaises se sont coordonnées sous la forme d’une association loi 1901. Le 2 octobre 2019, le nombre d’UNT participant à l’association est passé à 6. L’Université Numérique, regroupe plus d’une centaine d’établissements d’enseignement supérieur et de recherche français.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>[1]&nbsp;sciences de l’ingénieur et technologie (<a href=\"http://www.unit.eu/\" target=\"_blank\" rel=\"noreferrer noopener\">UNIT</a>) – sciences fondamentales (<a href=\"https://www.unisciel.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNISCIEL</a>) – économie-gestion (<a href=\"http://www.aunege.org/\" target=\"_blank\" rel=\"noreferrer noopener\">AUNEGE</a>) – sciences humaines et sociales, langues et cultures (<a href=\"https://www.uoh.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UOH</a>) – sciences juridiques et politiques (<a href=\"https://www.unjf.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNJF</a>) – environnement et développement durable (<a href=\"http://www.uved.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UVED</a>) – sciences de la santé et du sport (<a href=\"https://www.uness.fr/\" target=\"_blank\" rel=\"noreferrer noopener\">UNESS</a>) – technologie (<a href=\"https://www.iutenligne.net/\" target=\"_blank\" rel=\"noreferrer noopener\">IUT en Ligne</a>)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"uness\"} -->\n<h2 class=\"wp-block-heading uness\">Les missions des UNT</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT ont été créées dans un objectif de&nbsp;<strong>mutualisation</strong>, en vue d’encourager les usages du numérique lors des séances pédagogiques dans l’enseignement supérieur. Cette mutualisation passe par la production de ressources pédagogiques numériques, pour la plupart accessibles librement à travers les sites internet des UNT. Ces ressources sont conçues dans le but d’<strong>aider les enseignants dans leur pédagogie</strong>, contribuant ainsi à la rénovation des pédagogies et à l’innovation par le numérique dans l’enseignement supérieur.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Les principales missions des UNT sont&nbsp;:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>accompagner les étudiants de la Licence au Master, avec un soutien particulier en L1, l’ambition étant d’améliorer les taux de réussite&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>aider à l’orientation des étudiants et futurs étudiants&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>faciliter la formation tout au long de la vie&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>diffuser la connaissance pour toutes et tous dans un souci de service public&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>faciliter l’enseignement à distance, notamment à destination des personnes empêchées (en situation de handicap, prisonniers, etc.)&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>promouvoir les TICE&nbsp;et appuyer les établissements pour la mise en place des usages liés à la pédagogie numérique&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>co-construire et gérer des projets pluri-partenaires axés sur le numérique&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>promouvoir les établissements et les auteurs dans leurs spécialités&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>favoriser la mobilité internationale et l’intégration des étudiants étrangers&nbsp;;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>inscrire la France dans le mouvement mondial de libéralisation de l’accès au savoir.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>L’association L’Université Numérique promeut 6 UNT dans une vision commune. Elle vise à développer des actions collectives (Festival d’Automne du Numérique (FAN), appel à projets pour la production et la réingénierie de ressources à destination des publics « oui, si ») et à valoriser les actions de chacune des UNT et celles de leurs établissements, de manière plus visible et dans le respect de leurs spécificités.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":14241,\"sizeSlug\":\"full\",\"linkDestination\":\"media\",\"align\":\"center\",\"style\":{\"color\":[]}} -->\n<figure class=\"wp-block-image aligncenter size-full\"><a href=\"http://un.test/wp-content/uploads/2025/07/Collaboration-1-1030x687-1.jpg\"><img src=\"http://un.test/wp-content/uploads/2025/07/Collaboration-1-1030x687-1.jpg\" alt=\"\" class=\"wp-image-14241\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"className\":\"uved\"} -->\n<h2 class=\"wp-block-heading uved\">Les accompagnements possibles</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Par son action pour les établissements de l’enseignement supérieur, l’Université Numérique répond à multiples défis et objectifs&nbsp;:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Lutter contre l’échec en premier cycle</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Simplifier la situation des étudiants empêchés</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Favoriser l’intégration des étudiants en situation de handicap</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Servir d’appui à la mobilité internationale entrante et sortante</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Préserver des connaissances et compétences disciplinaires rares</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Appuyer la transformation et la mise en place de l’offre de formation des CUE</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Accompagner l’évolution des pratiques pédagogiques notamment avec le numérique</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Monter ou participer à des projets pluri-partenaires</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"className\":\"unit\"} -->\n<h2 class=\"wp-block-heading unit\">Les ressources pédagogiques numériques</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT mettent à disposition et diffusent environ 30.000 ressources éducatives libres dont elles ont souvent financé en partie la production. Elles peuvent en&nbsp;<strong>accompagner les usages</strong>. Elles produisent également des MOOC, des tests de positionnement transversaux et disciplinaires, des ressources de remédiation associées, des dispositifs de découverte des disciplines universitaires, des parcours de formation (ressources structurées et scénarios de formation), etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>De nombreuses ressources extérieures aux UNT (existantes, produites par les établissements) sont également indexées sur les portails disciplinaires.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>L\'Université Numérique est fière d\'être le partenaire privilégié de <a href=\"https://www.canal-u.tv/\" target=\"_blank\" rel=\"noreferrer noopener\">Canal U</a>, la vidéothèque dédiée à l\'enseignement supérieur et la recherche. Remontant à nos débuts, les Universités Numériques Thématiques ont joué un rôle crucial dans le fonctionnement de Canal U, en particulier dans la gestion des disciplines pour le classement des vidéos, une collaboration qui s\'étend jusqu\'à l\'année 2022. Bien que la classification actuelle soit désormais indépendante, elle demeure un héritage des Universités Numériques Thématiques. Par ailleurs, les UNT disposent chacune d\'une chaine sur Canal-U.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Canal U se distingue en offrant un entrepôt OAI, des DOI et en utilisant le SupLomFr pour garantir une expérience utilisateur exceptionnelle. Notre partenariat avec l\'ABES va au-delà, avec l\'utilisation d\'IdREF, attribuant des identifiants uniques aux mots-clés et aux intervenants. Ainsi, leurs contributions audiovisuelles sont référencées au même titre que leurs écrits, renforçant la richesse et la pertinence de notre vidéothèque.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"uoh\"} -->\n<h2 class=\"wp-block-heading uoh\">La transformation pédagogique par le numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Les UNT contribuent à la rénovation de de la pédagogie en favorisant la créativité pédagogique par l’usage du numérique.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Elles sont devenues des acteurs incontournables de la transformation pédagogique par le numérique et sont complémentaires des autres acteurs du domaine.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"iut\"} -->\n<h2 class=\"wp-block-heading iut\">Les instances de L\'Université Numérique</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Le conseil d\'administration est composé de :</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Vincent Beillevaire pour <a href=\"https://luniversitenumerique.fr/thematiques/sciences-ingenieur-technologie/\" target=\"_blank\" rel=\"noreferrer noopener\">UNIT</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Béatrice Boury pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/sante-et-sport/\" target=\"_blank\" rel=\"noreferrer noopener\">UNESS</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Jacques Dang pour <a href=\"https://luniversitenumerique.fr/thematiques/economie-gestion-marketing/\" target=\"_blank\" rel=\"noreferrer noopener\">AUNEGe</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Ollivier Haemmerlé pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/sciences-humaines-sociales-lettres-langues-arts/\" target=\"_blank\" rel=\"noreferrer noopener\">UOH</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Paula Caterino pour <a href=\"https://luniversitenumerique.fr/thematiques/enseignement-technologique/\" target=\"_blank\" rel=\"noreferrer noopener\">IUT en Ligne</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Delphine Pommeray pour l\'<a href=\"https://luniversitenumerique.fr/thematiques/environnement-developpement-durable/\" target=\"_blank\" rel=\"noreferrer noopener\">UVED</a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Le bureau est composé de :</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Ollivier Haemmerlé, Président</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Jacques Dang, Secrétaire</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Vincent Beillevaire, Trésorier</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','L\'Université Numérique','','inherit','closed','closed','','14237-revision-v1','','','2025-07-23 14:37:38','2025-07-23 12:37:38','',14237,'http://un.test/?p=14245',0,'revision','',0),
